/* kernel/arch/aarch64/vectors.S -- the counterpart to kernel/arch/x86_64/isr.s.
 *
 * WHAT IS DIFFERENT, and it is not a detail. On x86-64 there are 256
 * vectors, each one an address in a table the kernel builds, and the
 * processor picks the entry by NUMBER: vector 14 is a page fault, vector 32
 * is whatever the PIC was told to send. `isr.s` therefore has 256 stubs,
 * generated by a macro, and each one pushes its own number.
 *
 * AArch64 has SIXTEEN entries, and the processor picks by SITUATION, not by
 * cause: four groups (current EL on SP_EL0, current EL on SP_ELx, a lower
 * EL running AArch64, a lower EL running AArch32) times four kinds
 * (synchronous, IRQ, FIQ, SError). WHY the exception happened is not in the
 * entry, it is in ESR_EL1, which the handler reads. So there is no table of
 * 256 pointers here and nothing to fill in at run time; the table IS the
 * code, and VBAR_EL1 gets its address.
 *
 * THE TRAP THAT COST THIS FILE ONE REWRITE. The geometry is fixed by the
 * architecture: each of the sixteen entries is exactly 0x80 = 128 OCTETS OF
 * INSTRUCTION SPACE, and the table starts on a 2048-octet boundary. The
 * first version of this file put the whole register save inside each entry
 * -- about 200 octets. The assembler said nothing: `.balign 128` in front
 * of an entry that is longer than 128 simply starts the NEXT one late, and
 * everything shifts. What that looked like from outside was a deliberate
 * `svc #0` at EL1h being reported as entry 2 instead of entry 4, with the
 * right ESR value attached. Nothing crashed; the number was just wrong, in
 * a way that a table of function pointers on x86 cannot be wrong.
 *
 * So each entry here is FOUR instructions: open the frame, save x0 and x1,
 * put the entry number in x0, jump to the common part. Sixteen octets, and
 * room to spare.
 *
 * `.balign` and not `.align`: `.align 2048` in the AArch64 port of GNU as
 * asks for 2^2048 (round 80 found the same difference in the compiler,
 * where `.align 8` silently meant 256). `.balign` counts octets in both
 * ports and cannot be read two ways.
 *
 * The frame is 288 octets and holds x0..x30, ELR_EL1, SPSR_EL1, ESR_EL1 and
 * FAR_EL1. x30 is in there because a `bl` inside the handler would
 * otherwise eat the return address of the interrupted code -- on x86 the
 * same job is done by the fact that the interrupt itself pushed it.
 */

#include "virt.inc"

    .set FRAME_SIZE, 288
    .set F_X30,      240
    .set F_ELR,      248
    .set F_SPSR,     256
    .set F_ESR,      264
    .set F_FAR,      272

.macro VECTOR kind
    .balign 128
    sub     sp, sp, #FRAME_SIZE
    stp     x0, x1, [sp, #0]
    mov     x0, #\kind
    b       vector_common
.endm

    .section .text.vectors, "ax"
    .balign 2048
    .globl vector_table
vector_table:
    /* current EL, SP_EL0 */
    VECTOR 0        /* synchronous */
    VECTOR 1        /* IRQ         */
    VECTOR 2        /* FIQ         */
    VECTOR 3        /* SError      */
    /* current EL, SP_ELx -- this is where a kernel running at EL1h lands */
    VECTOR 4        /* synchronous */
    VECTOR 5        /* IRQ         */
    VECTOR 6        /* FIQ         */
    VECTOR 7        /* SError      */
    /* lower EL, AArch64 -- this is where EL0, that is ring 3, lands */
    VECTOR 8
    VECTOR 9
    VECTOR 10
    VECTOR 11
    /* lower EL, AArch32 -- Osum runs no 32-bit code; reported, not served */
    VECTOR 12
    VECTOR 13
    VECTOR 14
    VECTOR 15

/* The part that is too long to live inside an entry. On arrival:
 *   x0 = which of the sixteen entries was taken
 *   sp = the frame, with the original x0 and x1 already in it
 */
    .balign 128
vector_common:
    stp     x2,  x3,  [sp, #16]
    stp     x4,  x5,  [sp, #32]
    stp     x6,  x7,  [sp, #48]
    stp     x8,  x9,  [sp, #64]
    stp     x10, x11, [sp, #80]
    stp     x12, x13, [sp, #96]
    stp     x14, x15, [sp, #112]
    stp     x16, x17, [sp, #128]
    stp     x18, x19, [sp, #144]
    stp     x20, x21, [sp, #160]
    stp     x22, x23, [sp, #176]
    stp     x24, x25, [sp, #192]
    stp     x26, x27, [sp, #208]
    stp     x28, x29, [sp, #224]
    str     x30,      [sp, #F_X30]
    mrs     x1, elr_el1
    str     x1,       [sp, #F_ELR]
    mrs     x1, spsr_el1
    str     x1,       [sp, #F_SPSR]
    mrs     x1, esr_el1
    str     x1,       [sp, #F_ESR]
    mrs     x1, far_el1
    str     x1,       [sp, #F_FAR]

    mov     x1, x0                          /* which entry */
    mov     x0, sp                          /* the frame   */
    bl      arch_exception

    ldr     x0,       [sp, #F_ELR]
    msr     elr_el1, x0
    ldr     x0,       [sp, #F_SPSR]
    msr     spsr_el1, x0
    ldr     x30,      [sp, #F_X30]
    ldp     x28, x29, [sp, #224]
    ldp     x26, x27, [sp, #208]
    ldp     x24, x25, [sp, #192]
    ldp     x22, x23, [sp, #176]
    ldp     x20, x21, [sp, #160]
    ldp     x18, x19, [sp, #144]
    ldp     x16, x17, [sp, #128]
    ldp     x14, x15, [sp, #112]
    ldp     x12, x13, [sp, #96]
    ldp     x10, x11, [sp, #80]
    ldp     x8,  x9,  [sp, #64]
    ldp     x6,  x7,  [sp, #48]
    ldp     x4,  x5,  [sp, #32]
    ldp     x2,  x3,  [sp, #16]
    ldp     x0,  x1,  [sp, #0]
    add     sp, sp, #FRAME_SIZE
    eret
